    "Enter_the_name_of_the_tax_you_want_to_apply,_such_as_VAT,_GST,_or_Sales_Tax._This_name_will_be_visible_to_customers_on_invoices,_order_summaries,_and_checkout_pages,_so_make_sure_it_is_clear_and_recognizable." => "Saisissez le nom de la taxe à appliquer, par exemple TVA ou taxe sur les ventes. Ce nom sera visible par les clients sur les factures, récapitulatifs et pages de paiement, veillez donc à ce qu'il soit clair.",
    "Specify_the_value_of_the_tax_here._You_can_enter_a_number_(e.g.,_5,_10,_or_15)_and_then_choose_whether_it_should_be_applied_as_a_percentage_of_the_product_price_or_as_a_fixed_amount_from_the_dropdown_menu." => "Indiquez ici la valeur de la taxe. Vous pouvez saisir un nombre (par ex. 5, 10 ou 18) puis choisir s'il s'applique en pourcentage du prix ou comme montant fixe.",
    "Edit_Vat/Tax" => "Modifier la TVA / taxe",
